// AdminServiceHandler is an implementation of the admin.v1.AdminService service.
type AdminServiceHandler interface {
	// Returns comprehensive observability data including queue, load balancer, and dispatch stats.
	GetObservability(context.Context, *connect.Request[v1.GetObservabilityRequest]) (*connect.Response[v1.GetObservabilityResponse], error)
	// Returns Shopee affiliate link audit data to detect misconfigurations.
	GetShopeeAffiliateAudit(context.Context, *connect.Request[v1.GetShopeeAffiliateAuditRequest]) (*connect.Response[v1.GetShopeeAffiliateAuditResponse], error)
	// Ensures webhooks are configured for all instances on a given server.
	EnsureWebhooks(context.Context, *connect.Request[v1.EnsureWebhooksRequest]) (*connect.Response[v1.EnsureWebhooksResponse], error)
	// Returns recent webhook logs (admin only).
	ListWebhookLogs(context.Context, *connect.Request[v1.ListWebhookLogsRequest]) (*connect.Response[v1.ListWebhookLogsResponse], error)
	// Simulates a Kiwify webhook for testing (admin only).
	SimulateKiwifyWebhook(context.Context, *connect.Request[v1.SimulateKiwifyWebhookRequest]) (*connect.Response[v1.SimulateKiwifyWebhookResponse], error)
	// Returns system events filtered by user/instance and time window.
	GetSystemEvents(context.Context, *connect.Request[v1.GetSystemEventsRequest]) (*connect.Response[v1.GetSystemEventsResponse], error)
	// Resets a user's password (admin only).
	ResetUserPassword(context.Context, *connect.Request[v1.ResetUserPasswordRequest]) (*connect.Response[v1.ResetUserPasswordResponse], error)
	// Lists all plans (admin only).
	ListPlans(context.Context, *connect.Request[v1.ListPlansRequest]) (*connect.Response[v1.ListPlansResponse], error)
	// Creates a new plan (admin only).
	CreatePlan(context.Context, *connect.Request[v1.CreatePlanRequest]) (*connect.Response[v1.CreatePlanResponse], error)
	// Updates an existing plan (admin only).
	UpdatePlan(context.Context, *connect.Request[v1.UpdatePlanRequest]) (*connect.Response[v1.UpdatePlanResponse], error)
	// Deletes a plan (admin only).
	DeletePlan(context.Context, *connect.Request[v1.DeletePlanRequest]) (*connect.Response[v1.DeletePlanResponse], error)
	// Lists all email templates (admin only).
	ListEmailTemplates(context.Context, *connect.Request[v1.ListEmailTemplatesRequest]) (*connect.Response[v1.ListEmailTemplatesResponse], error)
	// Creates a new email template (admin only).
	CreateEmailTemplate(context.Context, *connect.Request[v1.CreateEmailTemplateRequest]) (*connect.Response[v1.CreateEmailTemplateResponse], error)
	// Updates an existing email template (admin only).
	UpdateEmailTemplate(context.Context, *connect.Request[v1.UpdateEmailTemplateRequest]) (*connect.Response[v1.UpdateEmailTemplateResponse], error)
	// Toggles email template active status (admin only).
	ToggleEmailTemplateActive(context.Context, *connect.Request[v1.ToggleEmailTemplateActiveRequest]) (*connect.Response[v1.ToggleEmailTemplateActiveResponse], error)
	// Lists all system users with pagination and filtering (admin only).
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	// Creates a new user (admin only).
	CreateUser(context.Context, *connect.Request[v1.CreateUserRequest]) (*connect.Response[v1.CreateUserResponse], error)
	// Updates a user's role (admin only).
	UpdateUserRole(context.Context, *connect.Request[v1.UpdateUserRoleRequest]) (*connect.Response[v1.UpdateUserRoleResponse], error)
	// Lists all users with admin role (admin only).
	ListAdminUsers(context.Context, *connect.Request[v1.ListAdminUsersRequest]) (*connect.Response[v1.ListAdminUsersResponse], error)
	// Grants admin role to a user (admin only).
	GrantAdminRole(context.Context, *connect.Request[v1.GrantAdminRoleRequest]) (*connect.Response[v1.GrantAdminRoleResponse], error)
	// Revokes admin role from a user (admin only).
	RevokeAdminRole(context.Context, *connect.Request[v1.RevokeAdminRoleRequest]) (*connect.Response[v1.RevokeAdminRoleResponse], error)
	// Unlocks a user account by clearing billing_status (admin only).
	// Used to restore access after payment issues are resolved.
	UnlockUserAccount(context.Context, *connect.Request[v1.UnlockUserAccountRequest]) (*connect.Response[v1.UnlockUserAccountResponse], error)
	// Gets detailed user investigation data (instances, automations).
	GetUserInvestigation(context.Context, *connect.Request[v1.GetUserInvestigationRequest]) (*connect.Response[v1.GetUserInvestigationResponse], error)
	// Spreads next_run_at across user's automations.
	AdminSpreadAutomationSchedule(context.Context, *connect.Request[v1.AdminSpreadAutomationScheduleRequest]) (*connect.Response[v1.AdminSpreadAutomationScheduleResponse], error)
	// Returns aggregated profile statistics for the admin dashboard.
	GetAdminProfileStats(context.Context, *connect.Request[v1.GetAdminProfileStatsRequest]) (*connect.Response[v1.GetAdminProfileStatsResponse], error)
	// Lists all categories with optional subcategories (admin only).
	ListCategories(context.Context, *connect.Request[v1.ListCategoriesRequest]) (*connect.Response[v1.ListCategoriesResponse], error)
	// Creates a new category (admin only).
	CreateCategory(context.Context, *connect.Request[v1.CreateCategoryRequest]) (*connect.Response[v1.CreateCategoryResponse], error)
	// Updates an existing category (admin only).
	UpdateCategory(context.Context, *connect.Request[v1.UpdateCategoryRequest]) (*connect.Response[v1.UpdateCategoryResponse], error)
	// Deletes a category (admin only, only non-system categories).
	DeleteCategory(context.Context, *connect.Request[v1.DeleteCategoryRequest]) (*connect.Response[v1.DeleteCategoryResponse], error)
	// Creates a new subcategory (admin only).
	CreateSubcategory(context.Context, *connect.Request[v1.CreateSubcategoryRequest]) (*connect.Response[v1.CreateSubcategoryResponse], error)
	// Updates an existing subcategory (admin only).
	UpdateSubcategory(context.Context, *connect.Request[v1.UpdateSubcategoryRequest]) (*connect.Response[v1.UpdateSubcategoryResponse], error)
	// Deletes a subcategory (admin only, only non-system subcategories).
	DeleteSubcategory(context.Context, *connect.Request[v1.DeleteSubcategoryRequest]) (*connect.Response[v1.DeleteSubcategoryResponse], error)
}

